import type { MediaSourceInterface } from "@unomed/react-native-matrix-sdk";
import { MatrixCore } from "../services/MatrixCore";
import { getHttpUriForMxc } from "./getHttpUriForMxc";

interface PropsWithUrl {
  url: string;
  serverUrl: string;
  width?: number;
  height?: number;
  resizeMode?: "scale" | "crop";
}

interface PropsWithMediaSource {
  serverUrl: string;
  mediaSource: MediaSourceInterface;
  mimeType?: string;
}

type Props = PropsWithUrl | PropsWithMediaSource;

/**
 * Fetches image from Matrix
 * For MediaSource: Handles both encrypted and unencrypted images automatically
 * For plain URL: Fetches from MXC URL (for avatars, etc.)
 */
export const fetchMedia = async (props: Props) => {
  if (!MatrixCore.instance) {
    throw new Error("Matrix client not initialized");
  }

  try {
    // Handle MediaSource (for message images - supports encryption)
    if ("mediaSource" in props) {
      const { mediaSource, mimeType = "image/jpeg" } = props;

      // Use SDK's getMediaFile which handles decryption automatically
      // Note: useCache is set to false to prevent stale temporary file paths
      // iOS clears /tmp directory periodically, which would invalidate cached paths
      const mediaHandle = await MatrixCore.instance.getMediaFile(
        mediaSource,
        undefined, // filename
        mimeType,
        false, // useCache - disabled to prevent stale temp file issues
        undefined, // tempDir - uses system default
      );

      const filePath = mediaHandle.path();
      return filePath.startsWith("file://") ? filePath : `file://${filePath}`;
    }

    // Handle plain URL (for avatars, room images - typically unencrypted)
    const {
      url,
      width = 32,
      height = 32,
      resizeMode = "scale",
      serverUrl,
    } = props;

    const uri = getHttpUriForMxc(
      serverUrl,
      url,
      width,
      height,
      resizeMode,
      true,
      true,
      true,
    );

    if (!uri) return null;

    const res = await fetch(uri, {
      headers: {
        Authorization: `Bearer ${MatrixCore.instance.session().accessToken}`,
      },
    });

    return res.url;
  } catch (error) {
    console.error("Failed to fetch image:", error);
    return null;
  }
};

