import ReactNativeBlobUtil from "react-native-blob-util";

//TODO: Add encryption for cached images

const CacheDir = `${ReactNativeBlobUtil.fs.dirs.CacheDir}/images`;
const PrefixlessCacheDir = CacheDir.replace("file://", "");
const CurrentBatch = new Map<string, Promise<void>>();
let CacheDirReady = false;

function getFilenameByURL(url: string) {
  let hash = 0;
  for (let i = 0; i < url.length; i++) {
    hash = (hash << 5) - hash + url.charCodeAt(i);
    hash |= 0; // Convert to 32bit integer
  }
  return (hash >>> 0).toString(36);
}

/** Returns storage filename associated with provided URL, including the file:// prefix */
export function getCachedImagePathByURL(url: string) {
  const fileName = getFilenameByURL(url);
  // Ensure the base CacheDir is just a path, not prefixed, before joining.
  // Then add the file:// prefix at the end.
  return `file://${PrefixlessCacheDir}/${fileName}`;
}

function getStoragePathByUrl(url: string) {
  const fileName = getFilenameByURL(url);
  return `${PrefixlessCacheDir}/${fileName}`;
}

async function downloadToPath(url: string, localFilePath: string) {
  const responseRaw = await ReactNativeBlobUtil.config({
    path: localFilePath,
  }).fetch("GET", url);

  const response = responseRaw.info();
  const status = response.status;

  if (status < 200 || status >= 300) {
    // Remove invalid cached file
    await ReactNativeBlobUtil.fs.unlink(localFilePath);
    throw new Error(`Unable to cache ${url}, http ${status}`);
  }
}

async function ensureCached(
  cacheKey: string,
  downloadUrl: string,
): Promise<void> {
  if (CurrentBatch.has(cacheKey)) {
    return CurrentBatch.get(cacheKey);
  }

  const localFilePath = getStoragePathByUrl(cacheKey);
  const cachingPromise = (async () => {
    try {
      if (!CacheDirReady) {
        const dirExists = await ReactNativeBlobUtil.fs.exists(CacheDir);
        if (!dirExists) await ReactNativeBlobUtil.fs.mkdir(CacheDir);
        CacheDirReady = true;
      }

      const fileExists = await ReactNativeBlobUtil.fs.exists(localFilePath);
      if (!fileExists) {
        await downloadToPath(downloadUrl, localFilePath);
      } else {
        const stat = await ReactNativeBlobUtil.fs.stat(localFilePath);
        if (!stat || stat.size === 0) {
          await ReactNativeBlobUtil.fs.unlink(localFilePath);
          await downloadToPath(downloadUrl, localFilePath);
        }
      }
    } catch (error) {
      console.warn(
        `Failed to cache image ${downloadUrl} to ${localFilePath}:`,
        error,
      );
    } finally {
      CurrentBatch.delete(cacheKey);
    }
  })();

  CurrentBatch.set(cacheKey, cachingPromise);
  return cachingPromise;
}

/** Returns true if the image for the given URL is already cached on disk. */
export async function isCached(url: string): Promise<boolean> {
  const localFilePath = getStoragePathByUrl(url);
  try {
    const fileExists = await ReactNativeBlobUtil.fs.exists(localFilePath);
    if (!fileExists) return false;
    const stat = await ReactNativeBlobUtil.fs.stat(localFilePath);
    return !!stat && stat.size > 0;
  } catch {
    return false;
  }
}

/**
 * Caches downloaded image and returns a Promise that resolves when the image is fully written.
 * Handles concurrent requests for the same URL.
 */
export async function cacheImage(url: string): Promise<void> {
  return ensureCached(url, url);
}

/**
 * Caches an image using `cacheKey` as the cache identifier (e.g. MXC URL)
 * but downloads from `downloadUrl` (e.g. authenticated HTTP URL).
 */
export async function cacheImageWithKey(
  cacheKey: string,
  downloadUrl: string,
): Promise<void> {
  return ensureCached(cacheKey, downloadUrl);
}

/** Removes all cached images from disk. Call on logout. */
export async function clearImageCache(): Promise<void> {
  try {
    const dirExists = await ReactNativeBlobUtil.fs.exists(CacheDir);
    if (dirExists) {
      await ReactNativeBlobUtil.fs.unlink(CacheDir);
    }
  } catch (error) {
    console.warn("Failed to clear image cache:", error);
  } finally {
    CacheDirReady = false;
    CurrentBatch.clear();
  }
}

import { Block, Text } from "@prototyp/skeletor";
import {
  type EventTimelineItem,
  type ImageMessageContent,
  MessageType_Tags,
  MsgLikeKind_Tags,
  TimelineItemContent_Tags,
} from "@unomed/react-native-matrix-sdk";
import { useSetAtom } from "jotai";
import { MatrixBaseURL } from "modules/matrix-client/const";
import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
import { fetchMedia, getEventTextContent } from "modules/matrix-client/utils";
import { TimelineAtoms } from "modules/timeline/jotai";
import { TimelineService } from "modules/timeline/service/TimelineService";
import { type FC, useCallback, useEffect, useMemo, useState } from "react";
import { Image } from "react-native";
import {
  Loading,
  MessageTimestamp,
  PinIndicator,
  SeenBy,
} from "shared/components";
import { MAX_MEDIA_WIDTH } from "shared/const";
import { Colors, TextSize } from "shared/styles";
import {
  cacheImageWithKey,
  getCachedImagePathByURL,
  isCached,
} from "shared/utils/image-caching";
import { MessageLongPressWrapper } from "../message-long-press-wrapper";
import { MessageReactionsOverlay } from "../message-reactions-overlay";
import { MessageSender } from "../message-sender";

interface Props {
  roomId: string;
  event: EventTimelineItem;
  isPreviousSameSender: boolean;
  onMemberPress?: (member: MemberDetailsPayload) => void;
}

const getImageContent = (
  event: EventTimelineItem,
): ImageMessageContent | null => {
  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    const kind = event.content.inner.content.kind;
    if (kind?.tag === MsgLikeKind_Tags.Message) {
      const msgType = kind.inner.content.msgType;
      if (msgType?.tag === MessageType_Tags.Image) {
        return msgType.inner.content;
      }
    }
  }
  return null;
};

export const ImageMessage: FC<Props> = ({
  roomId,
  event,
  isPreviousSameSender,
  onMemberPress,
}) => {
  const content = getImageContent(event);
  const [messageWidth, setMessageWidth] = useState(40);
  const originalWidth = Number(content?.info?.thumbnailInfo?.width) || 0;
  const originalHeight = Number(content?.info?.thumbnailInfo?.height) || 0;
  const scaleRatio = Math.min(MAX_MEDIA_WIDTH / originalWidth, 1);
  const targetWidth = Math.round(originalWidth * scaleRatio);
  const targetHeight = Math.round(originalHeight * scaleRatio);
  const [uri, setUri] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const isUser = event.isOwn;
  const sender = event.senderProfile;
  const senderId = event.sender;
  const caption = content?.caption;
  const seenByUsers = TimelineService.getReadReceiptUsers(event);
  const background = useMemo(() => {
    if (!caption) return "transparent";
    return isUser ? Colors.primary : Colors.message;
  }, [caption, isUser]);
  const setImageViewerUri = useSetAtom(TimelineAtoms.imageViewerUri);

  const openImageViewer = useCallback(() => {
    if (!uri || isLoading) return;
    setImageViewerUri(uri);
  }, [uri, isLoading, setImageViewerUri]);

  useEffect(() => {
    if (!content) return;
    const mxcUrl = content.source.url();
    if (!mxcUrl) return;

    const load = async () => {
      try {
        if (await isCached(mxcUrl)) {
          setUri(getCachedImagePathByURL(mxcUrl));
          return;
        }

        const httpUrl = await fetchMedia({
          serverUrl:
            MatrixCore.instance?.session().homeserverUrl || MatrixBaseURL,
          mediaSource: content.source,
          mimeType: content.info?.mimetype || "image/jpeg",
        });

        if (!httpUrl) return;

        await cacheImageWithKey(mxcUrl, httpUrl);
        setUri(getCachedImagePathByURL(mxcUrl));
      } catch (error) {
        console.error(error);
      } finally {
        setIsLoading(false);
      }
    };

    load();
  }, [content]);

  if (!content) return null;

  return (
    <Block
      align={isUser ? "flex-end" : "flex-start"}
      margins={{ marginTop: isPreviousSameSender ? 6 : 16 }}
    >
      <MessageSender
        sender={sender}
        senderId={senderId}
        isUser={isUser}
        isPreviousSameSender={isPreviousSameSender}
        onMemberPress={onMemberPress}
      />
      <Block flexDirection={isUser ? "row-reverse" : "row"}>
        <Block
          background={background}
          border={{ borderRadius: 12 }}
          paddings={caption ? [4, 4, 12] : 0}
          gap={8}
        >
          <Block
            background="transparent"
            border={{
              borderRadius: 12,
            }}
            align="center"
            overflow="hidden"
            width={targetWidth}
            height={targetHeight}
            onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
          >
            {isLoading && (
              <Block
                absolute
                offsets={{ top: 0, left: 0, right: 0, bottom: 0 }}
                width="100%"
                height="100%"
                background={Colors.black70}
                align="center"
                justify="center"
                zIndex={1}
              >
                <Loading isFullScreen={false} />
              </Block>
            )}
            {uri && (
              <MessageLongPressWrapper
                event={event}
                content={getEventTextContent(event)}
                onFinalize={openImageViewer}
              >
                <Image
                  source={{ uri }}
                  width={targetWidth}
                  height={targetHeight}
                  resizeMode="contain"
                />
              </MessageLongPressWrapper>
            )}
          </Block>

          {caption ? (
            <Block
              maxWidth={targetWidth}
              justify="space-between"
              flexDirection={isUser ? "row-reverse" : "row"}
              gap={{
                row: 4,
                col: 16,
              }}
              align="center"
              flex={{ flexWrap: "wrap" }}
              paddings={[0, 8]}
              onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
            >
              <Text size={TextSize.small} color="white">
                {caption}
              </Text>
              <MessageTimestamp event={event} isUser={isUser} />
            </Block>
          ) : (
            <Block
              flexDirection={isUser ? "row" : "row-reverse"}
              gap={4}
              align="center"
              margins={{ marginLeft: isUser ? 0 : "auto" }}
            >
