import { Block, Text } from "@prototyp/skeletor";
import {
  type EventTimelineItem,
  type ImageMessageContent,
  MessageType_Tags,
  MsgLikeKind_Tags,
  TimelineItemContent_Tags,
} from "@unomed/react-native-matrix-sdk";
import { useSetAtom } from "jotai";
import { MatrixBaseURL } from "modules/matrix-client/const";
import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
import { fetchMedia, getEventTextContent } from "modules/matrix-client/utils";
import { TimelineAtoms } from "modules/timeline/jotai";
import { TimelineService } from "modules/timeline/service/TimelineService";
import { type FC, useCallback, useEffect, useMemo, useState } from "react";
import { Image } from "react-native";
import {
  Loading,
  MessageTimestamp,
  PinIndicator,
  SeenBy,
} from "shared/components";
import { MAX_MEDIA_WIDTH } from "shared/const";
import { Colors, TextSize } from "shared/styles";
import {
  cacheImageWithKey,
  getCachedImagePathByURL,
  isCached,
} from "shared/utils/image-caching";
import { MessageLongPressWrapper } from "../message-long-press-wrapper";
import { MessageReactionsOverlay } from "../message-reactions-overlay";
import { MessageSender } from "../message-sender";

interface Props {
  roomId: string;
  event: EventTimelineItem;
  isPreviousSameSender: boolean;
  onMemberPress?: (member: MemberDetailsPayload) => void;
}

const getImageContent = (
  event: EventTimelineItem,
): ImageMessageContent | null => {
  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    const kind = event.content.inner.content.kind;
    if (kind?.tag === MsgLikeKind_Tags.Message) {
      const msgType = kind.inner.content.msgType;
      if (msgType?.tag === MessageType_Tags.Image) {
        return msgType.inner.content;
      }
    }
  }
  return null;
};

export const ImageMessage: FC<Props> = ({
  roomId,
  event,
  isPreviousSameSender,
  onMemberPress,
}) => {
  const content = getImageContent(event);
  const [messageWidth, setMessageWidth] = useState(40);
  const originalWidth = Number(content?.info?.thumbnailInfo?.width) || 0;
  const originalHeight = Number(content?.info?.thumbnailInfo?.height) || 0;
  const scaleRatio = Math.min(MAX_MEDIA_WIDTH / originalWidth, 1);
  const targetWidth = Math.round(originalWidth * scaleRatio);
  const targetHeight = Math.round(originalHeight * scaleRatio);
  const [uri, setUri] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const isUser = event.isOwn;
  const sender = event.senderProfile;
  const senderId = event.sender;
  const caption = content?.caption;
  const seenByUsers = TimelineService.getReadReceiptUsers(event);
  const background = useMemo(() => {
    if (!caption) return "transparent";
    return isUser ? Colors.primary : Colors.message;
  }, [caption, isUser]);
  const setImageViewerUri = useSetAtom(TimelineAtoms.imageViewerUri);

  const openImageViewer = useCallback(() => {
    if (!uri || isLoading) return;
    setImageViewerUri(uri);
  }, [uri, isLoading, setImageViewerUri]);

  useEffect(() => {
    if (!content) return;
    const mxcUrl = content.source.url();
    if (!mxcUrl) return;

    const load = async () => {
      try {
        if (await isCached(mxcUrl)) {
          setUri(getCachedImagePathByURL(mxcUrl));
          return;
        }

        const httpUrl = await fetchMedia({
          serverUrl:
            MatrixCore.instance?.session().homeserverUrl || MatrixBaseURL,
          mediaSource: content.source,
          mimeType: content.info?.mimetype || "image/jpeg",
        });

        if (!httpUrl) return;

        await cacheImageWithKey(mxcUrl, httpUrl);
        setUri(getCachedImagePathByURL(mxcUrl));
      } catch (error) {
        console.error(error);
      } finally {
        setIsLoading(false);
      }
    };

    load();
  }, [content]);

  if (!content) return null;

  return (
    <Block
      align={isUser ? "flex-end" : "flex-start"}
      margins={{ marginTop: isPreviousSameSender ? 6 : 16 }}
    >
      <MessageSender
        sender={sender}
        senderId={senderId}
        isUser={isUser}
        isPreviousSameSender={isPreviousSameSender}
        onMemberPress={onMemberPress}
      />
      <Block flexDirection={isUser ? "row-reverse" : "row"}>
        <Block
          background={background}
          border={{ borderRadius: 12 }}
          paddings={caption ? [4, 4, 12] : 0}
          gap={8}
        >
          <Block
            background="transparent"
            border={{
              borderRadius: 12,
            }}
            align="center"
            overflow="hidden"
            width={targetWidth}
            height={targetHeight}
            onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
          >
            {isLoading && (
              <Block
                absolute
                offsets={{ top: 0, left: 0, right: 0, bottom: 0 }}
                width="100%"
                height="100%"
                background={Colors.black70}
                align="center"
                justify="center"
                zIndex={1}
              >
                <Loading isFullScreen={false} />
              </Block>
            )}
            {uri && (
              <MessageLongPressWrapper
                event={event}
                content={getEventTextContent(event)}
                onFinalize={openImageViewer}
              >
                <Image
                  source={{ uri }}
                  width={targetWidth}
                  height={targetHeight}
                  resizeMode="contain"
                />
              </MessageLongPressWrapper>
            )}
          </Block>

          {caption ? (
            <Block
              maxWidth={targetWidth}
              justify="space-between"
              flexDirection={isUser ? "row-reverse" : "row"}
              gap={{
                row: 4,
                col: 16,
              }}
              align="center"
              flex={{ flexWrap: "wrap" }}
              paddings={[0, 8]}
              onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
            >
              <Text size={TextSize.small} color="white">
                {caption}
              </Text>
              <MessageTimestamp event={event} isUser={isUser} />
            </Block>
          ) : (
            <Block
              flexDirection={isUser ? "row" : "row-reverse"}
              gap={4}
              align="center"
              margins={{ marginLeft: isUser ? 0 : "auto" }}
            >
              <MessageTimestamp event={event} isUser={isUser} />
            </Block>
          )}
        </Block>
        <PinIndicator event={event} />
      </Block>
      <MessageReactionsOverlay event={event} roomId={roomId} isUser={isUser} />
      <SeenBy users={seenByUsers} messageWidth={messageWidth} isUser={isUser} />
    </Block>
  );
};

import { ImageZoom } from "@likashefqet/react-native-image-zoom";
import { animateParallel, Block, Text } from "@prototyp/skeletor";
import { useAtom } from "jotai";
import { TimelineAtoms } from "modules/timeline/jotai";
import type { FC } from "react";
import { useCallback, useEffect, useRef, useState } from "react";
import { Dimensions, Modal, StyleSheet, TouchableOpacity } from "react-native";
import { Colors } from "shared/styles";
import {
  cacheImage,
  getCachedImagePathByURL,
} from "shared/utils/image-caching";
import { Button } from "../button";
import { Loading } from "../loading";

const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get("window");

const isLocalUri = (uri: string) => uri.startsWith("file://");

export const ImageViewerModal: FC = () => {
  const [imageViewerUri, setImageViewerUri] = useAtom(
    TimelineAtoms.imageViewerUri,
  );
  const [localUri, setLocalUri] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [hasError, setHasError] = useState(false);
  const [showControls, setShowControls] = useState(true);
  const visible = !!imageViewerUri;

  const controlsAnimation = useRef(
    animateParallel(
      { translateY: [-120, 0], opacity: [0, 1] },
      { duration: 280 },
    ),
  ).current;

  useEffect(() => {
    if (showControls) controlsAnimation.start();
    else controlsAnimation.reverse();
  }, [showControls]);

  useEffect(() => {
    if (!imageViewerUri) return;

    let cancelled = false;
    setLocalUri(null);
    setIsLoading(true);
    setHasError(false);

    const load = async () => {
      try {
        if (isLocalUri(imageViewerUri)) {
          setLocalUri(imageViewerUri);
          return;
        }

        await cacheImage(imageViewerUri);
        if (cancelled) return;
        setLocalUri(getCachedImagePathByURL(imageViewerUri));
      } catch {
        if (cancelled) return;
        setIsLoading(false);
        setHasError(true);
      }
    };

    load();

    return () => {
      cancelled = true;
    };
  }, [imageViewerUri]);

  const onClose = useCallback(() => {
    setImageViewerUri(null);
    setLocalUri(null);
    setHasError(false);
    setIsLoading(true);
    setShowControls(true);
  }, [setImageViewerUri]);

  const handleSingleTap = useCallback(() => {
    setShowControls((prev) => !prev);
  }, []);

  const handleImageLoad = useCallback(() => {
    setIsLoading(false);
    setHasError(false);
  }, []);

  const handleImageError = useCallback(() => {
    setIsLoading(false);
    setHasError(true);
  }, []);

  const handleRetry = useCallback(async () => {
    if (!imageViewerUri) return;
    setLocalUri(null);
    setIsLoading(true);
    setHasError(false);

    try {
      if (isLocalUri(imageViewerUri)) {
        setLocalUri(imageViewerUri);
        return;
      }

      await cacheImage(imageViewerUri);
      setLocalUri(getCachedImagePathByURL(imageViewerUri));
    } catch {
      setIsLoading(false);
      setHasError(true);
    }
  }, [imageViewerUri]);

  if (!visible) return null;

  return (
    <Modal
      visible={visible}
      animationType="fade"
      statusBarTranslucent
      transparent
      onRequestClose={onClose}
    >
      <Block background={Colors.black} flex={1} justify="center" align="center">
        <Block
          absolute
          offsets={{ top: 0, left: 0, right: 0 }}
          zIndex={10}
          paddings={[56, 20, 16, 20]}
          align="flex-end"
          background={Colors.primary}
          animations={controlsAnimation.animations}
          pointerEvents={showControls ? "auto" : "none"}
        >
          <Button.Wrapper onPress={onClose}>
            <Text size={17} font="InstrumentSans-Semibold" color={Colors.white}>
              Close
            </Text>
          </Button.Wrapper>
        </Block>

        <Block width={SCREEN_WIDTH} height={SCREEN_HEIGHT}>
          {isLoading && !hasError && (
            <Block
              absolute
              width={SCREEN_WIDTH}
              height={SCREEN_HEIGHT}
              align="center"
              justify="center"
              zIndex={5}
              background={Colors.black70}
            >
              <Loading isFullScreen={false} />
            </Block>
          )}

          {hasError ? (
            <Block
              width={SCREEN_WIDTH}
              height={SCREEN_HEIGHT}
              align="center"
              justify="center"
            >
              <Text size={16} color={Colors.white}>
                Failed to load image
              </Text>
              <TouchableOpacity
                onPress={handleRetry}
                style={styles.retryButton}
              >
                <Text size={14} color={Colors.white}>
                  Tap to retry
                </Text>
              </TouchableOpacity>
            </Block>
          ) : localUri ? (
            <ImageZoom
              key={localUri}
              uri={localUri}
              minScale={1}
              maxScale={5}
              maxPanPointers={2}
              isPanEnabled
              isPinchEnabled
              isDoubleTapEnabled
              isSingleTapEnabled
              style={styles.image}
              onLoad={handleImageLoad}
              onError={handleImageError}
              onSingleTap={handleSingleTap}
            />
          ) : null}
        </Block>
      </Block>
    </Modal>
  );
};

const styles = StyleSheet.create({
  container: {
    width: SCREEN_WIDTH,
    height: SCREEN_HEIGHT,
  },
  image: {
    width: SCREEN_WIDTH,
    height: SCREEN_HEIGHT,
  },
  retryButton: {
    marginTop: 12,
    paddingVertical: 8,
    paddingHorizontal: 16,
  },
});

import { Block, Text } from "@prototyp/skeletor";
import {
  type EventTimelineItem,
  MessageType_Tags,
  MsgLikeKind_Tags,
  TimelineItemContent_Tags,
  type VideoMessageContent,
} from "@unomed/react-native-matrix-sdk";
import { useSetAtom } from "jotai";
import { MatrixBaseURL } from "modules/matrix-client/const";
import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
import { fetchMedia, getEventTextContent } from "modules/matrix-client/utils";
import { TimelineAtoms } from "modules/timeline/jotai";
import { TimelineService } from "modules/timeline/service/TimelineService";
import { type FC, useCallback, useEffect, useMemo, useState } from "react";
import { Image } from "react-native";
import { Blurhash } from "react-native-blurhash";
import {
  MessageTimestamp,
  PinIndicator,
  SeenBy,
} from "shared/components";
import { MAX_MEDIA_WIDTH } from "shared/const";
import { Colors, TextSize } from "shared/styles";
import {
  cacheImageWithKey,
  getCachedImagePathByURL,
  isCached,
} from "shared/utils/image-caching";
import { MessageLongPressWrapper } from "../message-long-press-wrapper";
import { MessageReactionsOverlay } from "../message-reactions-overlay";
import { MessageSender } from "../message-sender";

interface Props {
  roomId: string;
  event: EventTimelineItem;
  isPreviousSameSender: boolean;
  onMemberPress?: (member: MemberDetailsPayload) => void;
}

const getVideoContent = (
  event: EventTimelineItem,
): VideoMessageContent | null => {
  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    const kind = event.content.inner.content.kind;
    if (kind?.tag === MsgLikeKind_Tags.Message) {
      const msgType = kind.inner.content.msgType;
      if (msgType?.tag === MessageType_Tags.Video) {
        return msgType.inner.content;
      }
    }
  }
  return null;
};

export const VideoMessage: FC<Props> = ({
  roomId,
  event,
  isPreviousSameSender,
  onMemberPress,
}) => {
  const content = getVideoContent(event);
  const [messageWidth, setMessageWidth] = useState(40);
  const thumbInfoWidth = Number(content?.info?.thumbnailInfo?.width) || 0;
  const thumbInfoHeight = Number(content?.info?.thumbnailInfo?.height) || 0;
  const originalWidth = thumbInfoWidth || Number(content?.info?.width) || 0;
  const originalHeight = thumbInfoHeight || Number(content?.info?.height) || 0;
  const scaleRatio = Math.min(MAX_MEDIA_WIDTH / originalWidth, 1);
  const targetWidth = Math.round(originalWidth * scaleRatio);
  const targetHeight = Math.round(originalHeight * scaleRatio);
  const [thumbnailUri, setThumbnailUri] = useState<string | null>(null);
  const isUser = event.isOwn;
  const sender = event.senderProfile;
  const senderId = event.sender;
  const caption = content?.caption;
  const blurhash = content?.info?.blurhash;
  const background = useMemo(() => {
    if (!caption) return "transparent";
    return isUser ? Colors.primary : Colors.message;
  }, [caption, isUser]);
  const seenByUsers = TimelineService.getReadReceiptUsers(event);
  const setVideoViewerContent = useSetAtom(TimelineAtoms.videoViewerContent);

  const openVideoViewer = useCallback(() => {
    if (!content) return;
    setVideoViewerContent(content);
  }, [content, setVideoViewerContent]);

  useEffect(() => {
    const thumbSource = content?.info?.thumbnailSource;
    if (!thumbSource) return;
    const mxcUrl = thumbSource.url();
    if (!mxcUrl) return;

    const load = async () => {
      try {
        if (await isCached(mxcUrl)) {
          setThumbnailUri(getCachedImagePathByURL(mxcUrl));
          return;
        }
        const fetchedUri = await fetchMedia({
          serverUrl:
            MatrixCore.instance?.session().homeserverUrl || MatrixBaseURL,
          mediaSource: thumbSource,
          mimeType: "image/jpeg",
        });
        if (!fetchedUri) return;
        await cacheImageWithKey(mxcUrl, fetchedUri);
        setThumbnailUri(getCachedImagePathByURL(mxcUrl));
      } catch (e) {
        console.error(e);
      }
    };

    load();
  }, [content]);

  if (!content) return null;

  return (
    <Block
      align={isUser ? "flex-end" : "flex-start"}
      margins={{ marginTop: isPreviousSameSender ? 6 : 16 }}
    >
      <MessageSender
        sender={sender}
        senderId={senderId}
        isUser={isUser}
        isPreviousSameSender={isPreviousSameSender}
        onMemberPress={onMemberPress}
      />

      <Block flexDirection={isUser ? "row-reverse" : "row"}>
        <Block
          background={background}
          border={{ borderRadius: 12 }}
          paddings={caption ? [4, 4, 12] : 0}
          gap={8}
        >
          <MessageLongPressWrapper
            event={event}
            content={getEventTextContent(event)}
            onFinalize={openVideoViewer}
          >
            <Block
              background="transparent"
              border={{ borderRadius: 12 }}
              align="center"
              overflow="hidden"
              width={targetWidth}
              height={targetHeight}
              onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
            >
              {blurhash && !thumbnailUri && (
                <Blurhash
                  blurhash={blurhash}
                  style={{ width: targetWidth, height: targetHeight }}
                  resizeMode="cover"
                />
              )}

              {thumbnailUri && (
                <Image
                  source={{ uri: thumbnailUri }}
                  style={{ width: targetWidth, height: targetHeight }}
                  resizeMode="cover"
                />
              )}

              {/* Play button overlay */}
              <Block
                absolute
                offsets={{ top: 0, left: 0, right: 0, bottom: 0 }}
                zIndex={10}
                border={{ borderRadius: 12 }}
                align="center"
                justify="center"
                pointerEvents="none"
              >
                <Block
                  background={Colors.primary}
                  width={40}
                  height={40}
                  align="center"
                  justify="center"
                  border={{ borderRadius: 999 }}
                >
                  <Image
                    tintColor={Colors.white}
                    source={require("assets/icons/play.png")}
                  />
                </Block>
              </Block>
            </Block>
          </MessageLongPressWrapper>

          {caption ? (
            <Block
              maxWidth={targetWidth}
              justify="space-between"
              flexDirection={isUser ? "row-reverse" : "row"}
              gap={{
                row: 4,
                col: 16,
              }}
              align="center"
              flex={{ flexWrap: "wrap" }}
              paddings={[0, 8]}
              onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
            >
              <Text size={TextSize.small} color="white">
                {caption}
              </Text>
              <MessageTimestamp event={event} isUser={isUser} />
            </Block>
          ) : (
            <Block
              flexDirection={isUser ? "row" : "row-reverse"}
              gap={4}
              align="center"
              margins={{ marginLeft: isUser ? 0 : "auto" }}
            >
              <MessageTimestamp event={event} isUser={isUser} />
            </Block>
          )}
        </Block>
        <PinIndicator event={event} />
      </Block>
      <MessageReactionsOverlay event={event} roomId={roomId} isUser={isUser} />
      <SeenBy users={seenByUsers} messageWidth={messageWidth} isUser={isUser} />
    </Block>
  );
};

import { Block, Text, useAnimateParallel } from "@prototyp/skeletor";
import { useAtom } from "jotai";
import { MatrixBaseURL } from "modules/matrix-client/const";
import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
import { fetchMedia } from "modules/matrix-client/utils";
import { TimelineAtoms } from "modules/timeline/jotai";
import { type FC, useCallback, useEffect, useState } from "react";
import { Dimensions, Modal, TouchableWithoutFeedback } from "react-native";
import Video, { type OnLoadData } from "react-native-video";
import { Colors } from "shared/styles";
import {
  cacheVideoWithKey,
  extFromMimeType,
  getCachedVideoPathByURL,
  isVideoCached,
} from "shared/utils/video-caching";
import { Button } from "../button";
import { Loading } from "../loading";

const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get("window");

export const VideoViewerModal: FC = () => {
  const [videoViewerContent, setVideoViewerContent] = useAtom(
    TimelineAtoms.videoViewerContent,
  );
  const [localUri, setLocalUri] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [hasError, setHasError] = useState(false);
  const [showControls, setShowControls] = useState(true);
  const [naturalSize, setNaturalSize] = useState<{
    width: number;
    height: number;
  } | null>(null);

  const videoSize = naturalSize
    ? (() => {
        const scale = Math.min(
          SCREEN_WIDTH / naturalSize.width,
          SCREEN_HEIGHT / naturalSize.height,
        );
        return {
          width: Math.round(naturalSize.width * scale),
          height: Math.round(naturalSize.height * scale),
        };
      })()
    : { width: SCREEN_WIDTH, height: SCREEN_HEIGHT };

  const visible = !!videoViewerContent;

  const controlsAnimation = useAnimateParallel(
    { translateY: [-120, 0], opacity: [0, 1] },
    { duration: 280 },
  );

  useEffect(() => {
    if (showControls) controlsAnimation.start();
    else controlsAnimation.reverse();
  }, [showControls]);

  useEffect(() => {
    if (!videoViewerContent) return;

    let cancelled = false;
    setLocalUri(null);
    setIsLoading(true);
    setHasError(false);

    const load = async () => {
      const mxcUrl = videoViewerContent.source.url();
      const mimeType = videoViewerContent.info?.mimetype || "video/mp4";
      const ext = extFromMimeType(mimeType);

      try {
        if (mxcUrl && (await isVideoCached(mxcUrl, ext))) {
          if (!cancelled) setLocalUri(getCachedVideoPathByURL(mxcUrl, ext));
          return;
        }

        const fetchedUri = await fetchMedia({
          serverUrl:
            MatrixCore.instance?.session().homeserverUrl || MatrixBaseURL,
          mediaSource: videoViewerContent.source,
          mimeType,
        });

        if (cancelled) return;
        if (!fetchedUri) {
          setHasError(true);
          setIsLoading(false);
          return;
        }

        if (mxcUrl) {
          await cacheVideoWithKey(mxcUrl, fetchedUri, ext);
          if (!cancelled) setLocalUri(getCachedVideoPathByURL(mxcUrl, ext));
        } else {
          if (!cancelled) setLocalUri(fetchedUri);
        }
      } catch {
        if (!cancelled) {
          setHasError(true);
          setIsLoading(false);
        }
      }
    };

    load();

    return () => {
      cancelled = true;
    };
  }, [videoViewerContent]);

  const onClose = useCallback(() => {
    setVideoViewerContent(null);
    setLocalUri(null);
    setHasError(false);
    setIsLoading(false);
    setShowControls(true);
    setNaturalSize(null);
  }, [setVideoViewerContent]);

  const handleVideoLoad = useCallback((data: OnLoadData) => {
    setIsLoading(false);
    setHasError(false);
    setNaturalSize({
      width: data.naturalSize.width,
      height: data.naturalSize.height,
    });
  }, []);

  const handleVideoError = useCallback(() => {
    setIsLoading(false);
    setHasError(true);
  }, []);

  const handleTap = useCallback(() => {
    setShowControls((prev) => !prev);
  }, []);

  const handleRetry = useCallback(() => {
    if (!videoViewerContent) return;
    const content = videoViewerContent;
    setVideoViewerContent(null);
    setTimeout(() => setVideoViewerContent(content), 0);
  }, [videoViewerContent, setVideoViewerContent]);

  if (!visible) return null;

  return (
    <Modal
      visible={visible}
      animationType="fade"
      statusBarTranslucent
      transparent
      onRequestClose={onClose}
    >
      <Block background={Colors.black} flex={1} justify="center" align="center">
        <Block
          absolute
          offsets={{ top: 0, left: 0, right: 0 }}
          zIndex={10}
          paddings={[56, 20, 16, 20]}
          align="flex-end"
          background={Colors.primary}
          animations={controlsAnimation.animations}
          pointerEvents={showControls ? "auto" : "none"}
        >
          <Button.Wrapper onPress={onClose}>
            <Text size={17} font="InstrumentSans-Semibold" color={Colors.white}>
              Close
            </Text>
          </Button.Wrapper>
        </Block>

        <Block width={videoSize.width} height={videoSize.height}>
          {isLoading && !hasError && (
            <Block
              absolute
              width={videoSize.width}
              height={videoSize.height}
              align="center"
              justify="center"
              zIndex={5}
              background={Colors.black70}
            >
              <Loading isFullScreen={false} />
            </Block>
          )}

          {hasError ? (
            <Block
              width={videoSize.width}
              height={videoSize.height}
              align="center"
              justify="center"
            >
              <Text color={Colors.white}>Failed to load video</Text>
              <Button.Wrapper onPress={handleRetry}>
                <Text size={14} color={Colors.white}>
                  Tap to retry
                </Text>
              </Button.Wrapper>
            </Block>
          ) : localUri ? (
            <TouchableWithoutFeedback onPress={handleTap}>
              <Video
                source={{
                  uri: localUri,
                  type: videoViewerContent?.info?.mimetype || "video/mp4",
                }}
                style={{ width: videoSize.width, height: videoSize.height }}
                resizeMode="contain"
                controls
                paused={false}
                onLoad={handleVideoLoad}
                onError={handleVideoError}
              />
            </TouchableWithoutFeedback>
          ) : null}
        </Block>
      </Block>
    </Modal>
  );
};

import { Block, Text } from "@prototyp/skeletor";
import {
  type EventTimelineItem,
  MessageType_Tags,
  MsgLikeKind_Tags,
  type RoomInterface,
  TimelineItemContent_Tags,
} from "@unomed/react-native-matrix-sdk";
import { useSetAtom } from "jotai";
import { TimelineAtoms } from "modules/timeline/jotai";
import { type FC, useMemo, useState } from "react";
import { StyleSheet } from "react-native";
import { useMediaTimeline } from "screens/room-media/hooks";
import { Button } from "shared/components";
import { Colors, TextSize } from "shared/styles";
import { FilesList } from "../files-list";
import { MediaList } from "../media-list";

interface Props {
  room: RoomInterface;
}

type Tab = "media" | "files";

function isMediaItem(event: EventTimelineItem): boolean {
  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    const kind = event.content.inner.content.kind;
    if (kind?.tag === MsgLikeKind_Tags.Message) {
      const tag = kind.inner.content.msgType?.tag;
      return tag === MessageType_Tags.Image || tag === MessageType_Tags.Video;
    }
  }
  return false;
}

function isFileItem(event: EventTimelineItem): boolean {
  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    const kind = event.content.inner.content.kind;
    if (kind?.tag === MsgLikeKind_Tags.Message) {
      const tag = kind.inner.content.msgType?.tag;
      return tag === MessageType_Tags.File || tag === MessageType_Tags.Audio;
    }
  }
  return false;
}

export const MediaGallery: FC<Props> = ({ room }) => {
  const { mediaItems: allItems, loading } = useMediaTimeline({
    room,
    roomId: room.id(),
  });
  const [activeTab, setActiveTab] = useState<Tab>("media");
  const mediaItems = useMemo(() => allItems.filter(isMediaItem), [allItems]);
  const fileItems = useMemo(() => allItems.filter(isFileItem), [allItems]);
  const isMediaEmpty = !mediaItems.length;
  const isFileEmpty = !fileItems.length;
  const setImageViewerUri = useSetAtom(TimelineAtoms.imageViewerUri);
  const setVideoViewerUri = useSetAtom(TimelineAtoms.videoViewerUri);

  const handleSetActiveImageUri = (
    uri: string | null,
    type?: "image" | "video",
  ) => {
    if (!uri || !type) return;
    if (type === "image") {
      setImageViewerUri(uri);
      return;
    }
    setVideoViewerUri(uri);
  };

  return (
    <Block flex={1}>
      <Block flexDirection="row" margins={{ marginBottom: 16 }}>
        {(["media", "files"] as Tab[]).map((tab) => (
          <Button.Wrapper
            key={tab}
            onPress={() => setActiveTab(tab)}
            style={styles.tab}
          >
            <Block
              align="center"
              paddings={[10, 0]}
              border={{
                borderBottomWidth: 2,
                borderBottomColor:
                  activeTab === tab ? Colors.primary : Colors.white20,
              }}
            >
              <Text
                size={TextSize.small}
                color={activeTab === tab ? Colors.white : Colors.white50}
                textTransform="capitalize"
              >
                {tab}
              </Text>
            </Block>
          </Button.Wrapper>
        ))}
      </Block>

      {activeTab === "media" ? (
        <Block flex={1}>
          <MediaList
            items={mediaItems}
            loading={loading}
            isEmpty={isMediaEmpty}
            onPressItem={handleSetActiveImageUri}
          />
        </Block>
      ) : (
        <FilesList items={fileItems} loading={loading} isEmpty={isFileEmpty} />
      )}
    </Block>
  );
};

const styles = StyleSheet.create({
  tab: {
    flex: 1,
  },
});

